function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	angleMode(DEGREES);
}

function draw() {

	background(0)

	rotateX(66)

	noFill()
	stroke(255, 240, 220, 120) // soft ivory

	for(var i = 0; i < 20; i++) {
		var r = map(sin(frameCount / 2), -1, 1, 0, 255)
		var g = map(i, 0, 20, 0, 255)
		var b = map(cos(frameCount), -1, 1, 255, 0)

		beginShape()

		for(var j = 0; j <360; j+= 10) {
		var rad = i * 17
		var x = rad * cos(j)
		var y = rad * sin(j)
		var z = sin(frameCount * 2 + i * 12) * 50

		vertex(x, y, z)

		}
		endShape(CLOSE)
	}

}
